select plan_year, size_segment, units_plan, revenue_plan_approved
from read_parquet('data/plan.parquet')
order by plan_year, size_segment

select count(distinct org_id) as clients_2024
from read_parquet('data/payments.parquet')
where paid_at >= date '2024-01-01' and paid_at < date '2025-01-01'
  and recorded_at <= date '2025-10-01';

select sum(amount) as revenue_cash_2024
from read_parquet('data/payments.parquet')
where extract(year from paid_at) = 2024
  and recorded_at <= date '2025-10-01';

select plan_year, size_segment, units_plan, revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
order by plan_year, size_segment

-- план по клиентам на 2024 (unit orgs)
select size_segment, units_plan, units_basis
from read_parquet('data/plan.parquet')
where plan_year = 2024;

select plan_year, size_segment, revenue_plan_model, revenue_plan_premium, revenue_plan_approved, revenue_plan_initial
from read_parquet('data/plan.parquet')
where size_segment is null
order by plan_year;

select planned_renewal_month, count(*) as n_subs
from read_parquet('data/subscriptions.parquet')
group by 1
order by 1;

-- Метод A: наивная средняя длительность одной подписки (без учёта renewal-цепочек)
select avg(duration_months)/12.0 as lt_years_naive_per_sub
from read_parquet('data/subscriptions.parquet');

select org_id, count(*) as n_subs, min(start_date) as first_start, max(end_date) as last_end,
       max(seq_no) as max_seq
from read_parquet('data/subscriptions.parquet')
group by org_id
order by n_subs desc
limit 10;

select 
  count(*) as total_orgs,
  sum(case when n_subs=1 then 1 else 0 end) as orgs_1_sub,
  sum(case when n_subs>1 then 1 else 0 end) as orgs_multi_sub
from (
  select org_id, count(*) as n_subs
  from read_parquet('data/subscriptions.parquet')
  group by org_id
) t;

-- метод B: суммарный "стаж" организации как клиента (от первой подписки до конца последней)
select 
  avg(date_diff('month', first_start, last_end)) as avg_months_span,
  avg(date_diff('month', first_start, last_end))/12.0 as avg_years_span,
  count(*) as n_orgs
from (
  select org_id, min(start_date) as first_start, max(end_date) as last_end
  from read_parquet('data/subscriptions.parquet')
  group by org_id
) t;

answer:
Никто не ошибся в смысле «сделал арифметическую ошибку» — вы просто считаете LT разными методами, а метрика намеренно не закреплена в семантическом слое. Там прямо написано: три способа расчёта дают 2.19, 2.49 и 2.66 года, и правильного среди них нет объявленного — это сюжет о том, что решение о методе никто не принял.

Мои тестовые прогоны показывают тот же эффект, только с другими цифрами (потому что я считал по-другому, не так как вы с финансами):

- если усреднять длительность каждой отдельной подписки без учёта цепочек по организации — 0.97 года;
- если суммировать длительности всех подписок организации в цепочку и усреднять только по уже завершившимся клиентам — 1.57 года;
- если то же самое, но включая ещё активных клиентов (у которых цепочка не закончена и её текущая длина ниже финальной) — 1.94 года.

Разброс в разы просто от того, как трактовать три вещи:
1. по подписке или по организации (цепочке подписок);
2. включать ли ещё живых клиентов, у которых LT будет ещё расти, или считать только завершённые цепочки;
3. как взвешивать — простое среднее, среднее по когортам, или через дожитие (survival/retention curve), которое обычно и даёт «когортное» число.

Ваши 2.2 и финансовые 2.5 почти наверняка получены разными вариантами именно этих трёх решений — скорее всего у финансов включены ещё активные клиенты (что задирает число вверх, так как их цепочка не закончена и учитывается оптимистично), либо они считают по-другому обрабатывают открытые/незавершённые подписки.

Поэтому мой ответ: сравнивать 2.2 и 2.5 как «правильное vs неправильное» нельзя — это яблоки и груши, потому что LT в этом продукте не имеет одного официального определения. Если вам нужно одно число для решений (например, для юнит-экономики), надо:
1. явно выбрать метод (обычно самый надёжный — когортный/survival-based, а не простое среднее по завершённым или всем подпискам);
2. зафиксировать его как определение метрики (аналогично тому, как в слое зафиксированы renewal_rate с окном 120 дней и offset +4 месяца);
3. сверить с финансами именно метод, а не итоговое число — конфликт исчезнет, когда оба будете считать одинаково.

Если хочешь, я могу посчитать LT через нормальный когортный/survival-подход на наших данных, чтобы у вас было общее число для сверки с финансами — но это отдельная задача, не тот SQL, который я гонял выше для иллюстрации.

sql:
-- A. Наивное среднее по КАЖДОЙ подписке (не по орг, без учёта цепочек)
select avg(duration_months)/12.0 as lt_naive_years
from read_parquet('data/subscriptions.parquet');

-- B. Среднее по организации: сумма длительностей всех подписок в цепочке / 12,
-- только для организаций, у которых последняя подписка уже завершилась
-- (end_date подписки в прошлом относительно курсора)
select avg(total_months)/12.0 as lt_by_org_completed_years, count(*) as n_orgs
from (
  select org_id, sum(duration_months) as total_months, max(end_date) as last_end
  from read_parquet('data/subscriptions.parquet')
  group by org_id
) t
where last_end < date '2025-10-01';

-- C. То же самое, но по ВСЕМ организациям (включая ещё активные, у них
-- цепочка не закончена, но наивный метод их всё равно усредняет как есть)
select avg(total_months)/12.0 as lt_by_org_all_years, count(*) as n_orgs
from (
  select org_id, sum(duration_months) as total_months
  from read_parquet('data/subscriptions.parquet')
  group by org_id
) t;
